{
  "tecnicas": [
    {
      "tecnica": "Señalamiento por asociación + carga valorativa (etiquetado) con insinuación mediante comillas",
      "autor": "T. W. Adorno; E. Frenkel-Brunswik; D. J. Levinson; R. N. Sanford",
      "obra": "The Authoritarian Personality",
      "año": "1950",
      "cita_breve": "El prejuicio y la atribución de significado “por asociación” se refuerzan mediante marcos valorativos y estereotipos que simplifican la atribución moral/cognitiva a grupos."
    },
    {
      "tecnica": "Efecto de autoridad (apelación a credenciales institucionales) + encuadre de confirmación",
      "autor": "Robert B. Cialdini",
      "obra": "Influence: The Psychology of Persuasion",
      "año": "1984",
      "cita_breve": "La “autoridad” aumenta la probabilidad de aceptación de una afirmación; además, los mensajes persuasivos pueden estructurarse para que el público seleccione/retenga información coherente con la interpretación que se induce."
    },
    {
      "tecnica": "Normalización/realismo tranquilizador (presentar el contacto como paso lógico para reducir complejidad y conflicto de intereses)",
      "autor": "Kahneman, Daniel",
      "obra": "Thinking, Fast and Slow",
      "año": "2011",
      "cita_breve": "La gente tiende a aceptar evaluaciones intuitivas rápidas cuando el marco del mensaje hace que la situación parezca sencilla/estable, reduciendo la percepción de ambigüedad y carga cognitiva."
    },
    {
      "tecnica": "Reencuadre (framing) que minimiza causa/autoría y maximiza juicio moral/judicial individual (culpa por omisión)",
      "autor": "Daniel Kahneman",
      "obra": "Thinking, Fast and Slow",
      "año": "2011",
      "cita_breve": "Los resultados y responsabilidades pueden percibirse de forma distinta según el encuadre (framing), guiando el juicio hacia criterios morales/jurídicos focalizados en un responsable individual."
    },
    {
      "tecnica": "Selección enmarcada por insinuación (contigüidad política) para dirigir la interpretación crítica del vínculo",
      "autor": "Chomsky, Noam",
      "obra": "Manufacturing Consent: The Political Economy of the Mass Media (con Edward S. Herman)",
      "año": "1988",
      "cita_breve": "Los medios pueden dirigir la interpretación mediante selección y encuadre de información (agenda y marco) que orienta la comprensión del público hacia conclusiones preferidas."
    }
  ]
}
